/bin/bash -lc "node --input-type=module <<'JS'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { once } from 'node:events';
import { setTimeout as delay } from 'node:timers/promises';
const directory = await mkdtemp('./.launch-check-');
const child = spawn('npm', ['start'], { detached: true, env: { ...process.env, PORT: '18080', DB_PATH: "'`${directory}/workboard.sqlite` }, stdio: ['"'ignore', 'pipe', 'pipe'] });
let output = '';
child.stdout.on('data', chunk => { output += chunk; });
child.stderr.on('data', chunk => { output += chunk; });
try {
  let ready = false;
  for (let attempt = 0; attempt < 100; attempt++) {
    if (child.exitCode "'!== null) throw new Error(output);
    try {
      const response = await fetch('"'http://127.0.0.1:18080/health');
      if (response.status === 200 && JSON.stringify(await response.json()) === '{\"status\":\"ok\"}') { ready = true; break; }
    } catch {}
    await delay(25);
  }
  if ("'!ready) throw new Error(`Launch check failed: ${output}`);
  console.log('"'npm start: health endpoint passed with configured PORT and DB_PATH');
} finally {
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await delay(100);
  await rm(directory, { recursive: true, force: true });
}
JS
"

